<?php /* VIVA NOTE: List rooms with capacity, rent and status information. */ ?><div class="toolbar"><p>Room capacity, rent, occupancy and photos.</p><a class="btn" href="<?=e(url('/room/new'))?>">＋ Add room</a></div>
<section class="panel table-wrap" tabindex="0" aria-label="Rooms table, scroll horizontally"><table><thead><tr><th>Room</th><th>Property</th><th>Rent</th><th>Available</th><th>Reserved</th><th>Occupied</th><th>Availability</th><th></th></tr></thead><tbody><?php foreach($rooms as $r):?><tr><td><strong><?=e($r['room_label']?:'Room #'.$r['room_id'])?></strong><br><small><?=e(pill($r['room_type']))?></small></td><td><?=e($r['property_title'])?></td><td><?=e(cash($r['price']))?></td><td><?=e($r['available_slots']??0)?></td><td><?=e($r['reserved_slots']??0)?></td><td><?=e($r['occupied_slots']??0)?></td><?php [$stateLabel,$stateClass]=room_availability_state($r); ?><td><span class="availability-badge <?=e($stateClass)?>"><?=e($stateLabel)?></span></td><td><a class="btn small secondary" href="<?=e(url('/room/show',['id'=>$r['room_id']]))?>">Open</a></td></tr><?php endforeach;?><?php if(!$rooms):?><tr><td colspan="8" class="empty">No rooms yet.</td></tr><?php endif;?></tbody></table></section>
